import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a sanitized name.
     * <p>
     * The method rejects names that would cause the resulting file to be
     * located outside {@code dir}. It also removes any query component
     * (e.g., "?foo") that may appear in URLs or ZIP entry names.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain path separators)
     * @return a {@link File} that does not already exist
     * @throws IllegalArgumentException if the name resolves outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be null or empty");
        }

        // Strip query parameters that may be present in ZIP entry names
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths and paths that contain ".." components
        Path rawPath = Paths.get(name);
        if (rawPath.isAbsolute() || rawPath.normalize().toString().contains("..")) {
            throw new IllegalArgumentException("Invalid file name: " + name);
        }

        // Resolve the name against the target directory and normalize
        Path resolved = dir.toPath().resolve(rawPath).normalize();

        // Ensure the resolved path is still within the target directory
        Path normalizedDir = dir.toPath().normalize();
        if (!resolved.startsWith(normalizedDir)) {
            throw new IllegalArgumentException(
                "Zip archives with files escaping their root directory are not allowed: " + name);
        }

        // Build the File instance
        File file = resolved.toFile();

        // Handle duplicate names by appending "-n" before the extension
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
