/**
 * DefaultURLConstructor is responsible for determining the forward page
 * based on the incoming HTTP request. The original implementation simply
 * returned {@link HttpServletRequest#getPathInfo()}, which is vulnerable
 * to path‑traversal attacks because the value can be manipulated by an
 * attacker.  The updated implementation validates and sanitises the
 * path before returning it, ensuring that only safe, expected values are
 * forwarded.
 */
public class DefaultURLConstructor implements URLConstructor {

    private static final Logger LOG = Logger.getLogger(DefaultURLConstructor.class.getName());

    /* A very strict whitelist pattern that allows only alphanumeric
       characters, dots, underscores and hyphens.  This covers typical
       JSP page names such as "Wiki.jsp" or "PageInfo.jsp". */
    private static final Pattern VALID_PATH_PATTERN =
            Pattern.compile("^[a-zA-Z0-9._-]+$");

    // other methods

    /**
     * Returns the name of the JSP page to forward to.  The returned value
     * is derived from the request's path info but is first validated
     * against a whitelist to prevent path traversal or other injection
     * attacks.
     *
     * @param request the HTTP request that led to this page
     * @return a sanitized page name such as "Wiki.jsp", or {@code null}
     *         if the path is invalid or not present
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        if (pathInfo == null || pathInfo.isEmpty()) {
            return null; // No specific page requested
        }

        // Remove a leading slash if present
        if (pathInfo.startsWith("/")) {
            pathInfo = pathInfo.substring(1);
        }

        // Reject any path containing directory traversal sequences or
        // other suspicious characters
        if (pathInfo.contains("..") || pathInfo.contains("\\") || pathInfo.contains(":")) {
            LOG.warning("Rejected potentially malicious path: " + pathInfo);
            return null;
        }

        // Validate against the whitelist pattern
        if (!VALID_PATH_PATTERN.matcher(pathInfo).matches()) {
            LOG.warning("Path does not match whitelist pattern: " + pathInfo);
            return null;
        }

        return pathInfo;
    }

    // other methods
}
