private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    File canonicalTargetDir = targetDirectory.getCanonicalFile();
    Path targetDirPath = canonicalTargetDir.toPath();

    ArchiveEntry nextEntry = supplier.getNextReadableEntry();
    while (nextEntry != null) {
        String entryName = nextEntry.getName();

        // Reject absolute paths or paths that start with '/' or contain drive letters
        if (entryName.startsWith("/") || entryName.matches("^[a-zA-Z]:.*")) {
            throw new IOException("Entry name is absolute or contains drive letter: " + entryName);
        }

        // Normalize path to prevent traversal
        Path entryPath = Paths.get(entryName).normalize();

        // Resolve against target directory
        Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

        // Ensure resolved path is within target directory
        if (!resolvedPath.startsWith(targetDirPath)) {
            throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
        }

        File f = resolvedPath.toFile();

        if (nextEntry.isDirectory()) {
            if (!f.isDirectory() && !f.mkdirs()) {
                throw new IOException("failed to create directory " + f);
            }
        } else {
            File parent = f.getParentFile();
            if (!parent.isDirectory() && !parent.mkdirs()) {
                throw new IOException("failed to create directory " + parent);
            }
            try (OutputStream o = Files.newOutputStream(f.toPath(), StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(nextEntry, o);
            }
        }
        nextEntry = supplier.getNextReadableEntry();
    }
}
