private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is cached in lastStoredEntry
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Sanity checks for the expected size
    if (csize <= 0) {                     // zero or negative size – nothing to read
        return -1;
    }
    if (current.bytesRead >= csize) {     // already consumed all declared bytes
        return -1;
    }

    // Read more data into the internal buffer if needed
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {                    // underlying stream ended unexpectedly
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Calculate how many bytes we can actually read
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining;        // safe cast – remaining > 0 and <= Integer.MAX_VALUE
    }

    // Defensive guard against negative values caused by overflow
    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
