import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // other methods

    /**
     * Returns a secure representation of the body suitable for XPath evaluation.
     * <p>
     * The method now parses XML strings and wrapped files using a
     * {@link DocumentBuilderFactory} that has been configured to disable
     * external entity resolution and DTD processing, thereby mitigating XXE
     * attacks. If the body is already a {@link Document}, it is returned
     * unchanged. For all other types, the original type conversion logic
     * is preserved.
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }
        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
        }
        if (answer == null) {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext().getTypeConverter()
                        .convertTo(InputStream.class, exchange, body);
                // Parse the stream securely into a Document
                answer = parseSecure(new InputSource(is));
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Parse the string securely into a Document
                answer = parseSecure(new InputSource(new StringReader((String) body)));
            }
        }
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }
        return answer;
    }

    /**
     * Parses the given {@link InputSource} into a {@link Document} using a
     * {@link DocumentBuilderFactory} that has been hardened against XXE
     * attacks. The factory disables external DTDs, external schemas,
     * and enables secure processing.
     */
    private Document parseSecure(InputSource source) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory dbf = getSecureDocumentBuilderFactory();
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(source);
    }

    /**
     * Creates a {@link DocumentBuilderFactory} instance that is configured
     * to prevent XML External Entity (XXE) attacks. The configuration
     * disables DOCTYPE declarations, external DTDs, and external schema
     * access, and enables the secure processing feature.
     */
    private static DocumentBuilderFactory getSecureDocumentBuilderFactory() {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        try {
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Disallow DOCTYPE declaration
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external entities
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
