            // features, fall back to the default factory but log the issue.
            // Logging omitted for brevity; in production, use a logger.
        }
        dbf.setNamespaceAware(true);
        return dbf;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods

}
