            // Reuse factory from exchange if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            try {
                sfactory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);
            } catch (Exception e) {
                LOG.warn("SAXParserFactory does not support secure processing: {}", e.getMessage());
            }

            // Disable external entity processing
            try {
                sfactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
                sfactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                sfactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                // Prevent loading external DTDs
                sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            } catch (ParserConfigurationException e) {
                LOG.warn("Failed to set XXE protection features on SAXParserFactory: {}", e.getMessage());
            }

            sfactory.setNamespaceAware(true);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Apply the same security settings to the XMLReader
            try {
                xmlReader.setFeature("http://xml.org/sax/features/external-general-entities", false);
                xmlReader.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (SAXException e) {
                LOG.warn("Failed to set XXE protection features on XMLReader: {}", e.getMessage());
            }

        } catch (Exception ex) {
            LOG.error("Cannot create SAXParser/XMLReader due to {}", ex.getMessage(), ex);
            throw new SAXException("Failed to create secure SAXParser", ex);
        }

        return new SAXSource(xmlReader, inputSource);
    }

